function s(v){return String(v==null?'':v).trim();}
function nz(x){return s(x).toLowerCase().replace(/[^a-z0-9]/g,'');}
function ems(x){return (s(x).toLowerCase().match(/[a-z0-9._%+-]+@[a-z0-9-]+(\.[a-z0-9-]+)+/g)||[]).map(function(e){return e.replace(/\.+$/,'');});}
function col(o,f){var k=Object.keys(o).find(function(k){return k.toLowerCase().indexOf(f)>=0;});return k?s(o[k]):'';}
var mail=$('Read Mail correction').all().map(function(i){return i.json;});
var inv=$('Read INVESTORS').all().map(function(i){return i.json;});
var pipe=$('Read PIPELINE').all().map(function(i){return i.json;});
var yes=function(x){return s(x).toLowerCase()==='yes';};
var out=[];
for(var a=0;a<mail.length;a++){var m=mail[a];var firm=col(m,'firm');if(!firm)continue;
 var wrong=ems(col(m,'wrong'));var correct=ems(col(m,'correct'));var ce=correct[0]||'';
 var k=nz(firm);
 var hits=inv.filter(function(r){var n=nz(r.investor);if(!n)return false;var e=ems(r.email);var byName=n===k||(k.length>=5&&n.indexOf(k)===0)||(n.length>=5&&k.indexOf(n)===0);var byMail=e.some(function(x){return x===ce||wrong.indexOf(x)>=0;});return byName||byMail;});
 var names={};hits.forEach(function(r){names[s(r.investor)]=1;});
 var q=0,qWrong=[],sent=0,sentWrong=[],marked=0,reshare=0,sentBlank=0;
 pipe.forEach(function(p){if(!names[s(p.investor)])return;var pe=ems(p.email);var isS=yes(p.deal_shared);var isP=yes(p.pause);
  if(s(p.notes).indexOf('Re-share after wrong email')>=0)reshare++;
  if(s(p.next_action).toLowerCase().indexOf('wrong email')>=0)marked++;
  if(isS){sent++;var w=pe.some(function(x){return wrong.indexOf(x)>=0;});if(pe.length===0)sentBlank++;if(w&&s(p.next_action).toLowerCase().indexOf('wrong email')<0)sentWrong.push(s(p.deal_id)+' '+s(p.startup)+' <'+s(p.email)+'> pause='+s(p.pause)+' na='+s(p.next_action)+' resp='+s(p.investor_response).slice(0,20));}
  else if(!isP){q++;if(ce&&pe.indexOf(ce)<0)qWrong.push(s(p.deal_id)+' '+s(p.startup)+' <'+s(p.email)+'> due '+s(p.next_due));}});
 out.push({sheet_row:m.row_number,firm:firm,wrong:wrong.join(','),correct:correct.join(',')||col(m,'correct'),contact:col(m,'contact'),status:col(m,'updated on'),inv:hits.map(function(r){return r.row_number+':'+s(r.investor)+' <'+s(r.email)+'> cp='+s(r.contact_person)+' dnc='+s(r.do_not_contact)+(ce&&ems(r.email).indexOf(ce)>=0?' OK':' NOT-CORRECTED');}),queued_live:q,queued_wrong:qWrong.slice(0,10),queued_wrong_n:qWrong.length,sent:sent,sent_blank_email:sentBlank,sent_to_wrong_unmarked:sentWrong.slice(0,10),sent_to_wrong_unmarked_n:sentWrong.length,already_marked:marked,reshares:reshare});}
return [{json:{mail_keys:Object.keys(mail[0]||{}),pipe_keys:Object.keys(pipe[0]||{}),inv_keys:Object.keys(inv[0]||{}),pipeline_rows:pipe.length,rows:out}}];

function s(v){return String(v==null?'':v).trim();}
