var inv=$('Read INVESTORS').all().map(function(i){return i.json;});
var pipe=$('Read PIPELINE').all().map(function(i){return i.json;});
var th=$('Read Thesis correction').all().map(function(i){var o=i.json;return {row:o.row_number,v:Object.keys(o).filter(function(k){return k!=='row_number';}).map(function(k){return s(o[k]);})};});
var pre=['blinc','siana','piper','dsg'];
var res={};
pre.forEach(function(p){
 var ir=inv.filter(function(r){return nz(r.investor).indexOf(p)===0;});
 var names={};ir.forEach(function(r){names[s(r.investor)]=1;});
 var tr=th.filter(function(r){return nz(r.v[0]).indexOf(p)===0;}).map(function(r){return r.row+': '+r.v.join(' || ').slice(0,600);});
 var q=[],sentNoResp=[],sentResp=0,paused=0;
 pipe.forEach(function(x){if(!names[s(x.investor)])return;if(yes(x.deal_shared)){if(s(x.investor_response))sentResp++;else sentNoResp.push(s(x.deal_id)+' '+s(x.startup)+(yes(x.pause)?' [paused]':''));}else if(yes(x.pause))paused++;else q.push(x.row_number+' '+s(x.deal_id)+' '+s(x.startup)+' | due '+s(x.next_due)+' | '+s(x.owner)+' | '+s(x.match_type).slice(0,40)+' | '+s(x.email));});
 res[p]={investors:ir.map(function(r){var o={};Object.keys(r).forEach(function(k){if(s(r[k]))o[k]=s(r[k]).slice(0,200);});return o;}),thesis:tr,queued_live:q,sent_with_response:sentResp,sent_no_response:sentNoResp,queued_paused:paused};});
