var want=keys.filter(function(k){var l=k.toLowerCase();return l==='startup'||l.indexOf('sector')>=0||l.indexOf('stage')>=0||l.indexOf('raise')>=0||l.indexOf('revenue')>=0||l.indexOf('status')>=0||l.indexOf('active')>=0||l.indexOf('owner')>=0;});
